[DataEventHandler(tablestr(FMRental),DataEventType::Updating)]
public static void FMRentalUpdatingEvent(Common c, DataEventArgs e)
{
    FMRental rental = c;

    if (rental.orig().Vehicle != rental.Vehicle ||
        rental.orig().rentalLengthInDays() != rental.rentalLengthInDays())
    {
        FMTotalsEngineBase::GetInstance().calculateRentalVehicleRate(rental);
    }
}

[DataEventHandler(tablestr(FMRental),DataEventType::Inserting)]
public static void FMRentalInsertingEvent(Common c, DataEventArgs e)
{
    FMRental rental = c;

    FMTotalsEngineBase::GetInstance().calculateRentalVehicleRate(rental);
}
